with source as (
    select * from {{ source('baci', 'products') }}
),

renamed as (
    select
        code as hs6,
        description
    from source
)

select * from renamed

{#-
  The full-detail fact: year x exporter x importer x HS6, ~270M rows. Built incrementally by
  year with delete+insert, so adding a year (or re-running chosen years with
  --vars '{baci_years: [2024]}') only rewrites those partitions. A new BACI release revises
  every year: run with --full-refresh.
-#}
{{
  config(
    materialized='incremental',
    incremental_strategy='delete+insert',
    unique_key='year',
    on_schema_change='fail'
  )
}}

with flows as (
    select * from {{ ref('stg_baci__flows') }}
    {% if var('baci_years', none) %}
    where year in ({{ var('baci_years') | join(', ') }})
    {% elif is_incremental() %}
        where year > (select max(year) from {{ this }})
    {% endif %}
),

entities as (
    select
        baci_code,
        entity_code
    from {{ ref('int_country_entities') }}
),

final as (
    select
        flows.year,
        exporter.entity_code as exporter_code,
        importer.entity_code as importer_code,
        flows.hs6,
        flows.value_usd,
        flows.quantity_t
    from flows
    inner join entities as exporter on flows.exporter_code = exporter.baci_code
    inner join entities as importer on flows.importer_code = importer.baci_code
)

select * from final

{#-
  Exporter -> importer trade by HS4 heading and year, from var('routes_first_year') (2015):
  "where does a country send this product" and "which products inside a chapter flow between
  two countries". ~60M rows; built incrementally by year like fct_trade_hs6.
-#}
{{
  config(
    materialized='incremental',
    incremental_strategy='delete+insert',
    unique_key='year',
    on_schema_change='fail'
  )
}}

{#- Year filter as one expression, so the rendered SQL has the same shape in every mode. -#}
{%- set first_year = var('routes_first_year', 2015) -%}
{%- if var('baci_years', none) -%}
    {%- set year_filter = 'year in (' ~ (var('baci_years') | join(', ')) ~ ') and year >= ' ~ first_year -%}
{%- elif is_incremental() -%}
    {%- set year_filter = 'year > (select max(year) from ' ~ this ~ ')' -%}
{%- else -%}
    {%- set year_filter = 'year >= ' ~ first_year -%}
{%- endif %}

with flows as (
    select * from {{ ref('fct_trade_hs6') }}
    where {{ year_filter }}
)

select
    year,
    exporter_code,
    importer_code,
    left(hs6, 4) as hs4,
    sum(value_usd) as value_usd
from flows
group by all
